double get_true_objective_value_ackley(const Eigen::VectorXi &action_vector) {
        const Eigen::VectorXd action_vector_scaled = action_vector.cast<double>() * step_size;
        const Eigen::VectorXd transformed_action_vector = (ackley_rotation.topLeftCorner(dimension, dimension) * action_vector_scaled) - ackley_shift.head(dimension);

        constexpr double a = 20;
        constexpr double b = 0.2;

        double sum_sq = (transformed_action_vector.array().square()).sum() / dimension;
        const double sum_cos = (transformed_action_vector.array() * 2 * M_PI).cos().sum() / dimension;
        sum_sq = sqrt(sum_sq);
        const double result = (-a * exp(-b * sum_sq) - exp(sum_cos) + 20 + exp(1)) * 8; // scale value range to approx. [0;100]

        return result;
}

double ackley(const Eigen::VectorXi &action_vector, bool noisy) {
        return get_true_objective_value_ackley(action_vector) + random_normal(0, noisy * noise_level);
}
